#!/usr/bin/env node
// Sync the partner-API catalog (generated by protegey-backend: `npm run catalog:export`) into
// app/data/partner-api-catalog/, split so the /api-docs page ships only what it renders:
//   index.json            — conventions, sandbox scenarios, webhook delivery + event list,
//                           module titles / endpoint summaries / lifecycles (bundled, SSR-rendered)
//   modules/<key>.json    — one module's full endpoints, scenarios and response shapes (lazy chunk)
//   webhook-events.json   — every webhook event's payload fields + examples (lazy chunk)
//
// Source (first match wins):
//   1. `--from <path-or-url>` argument, or PARTNER_API_CATALOG_SOURCE env var
//   2. ../protegey-backend/docs/partner-api-catalog.json (sibling checkout)
//   3. https://api.protegey.com/public/partner-api-catalog (public endpoint)
import { existsSync } from 'node:fs'
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = join(root, 'app', 'data', 'partner-api-catalog')
const siblingFile = resolve(root, '..', 'protegey-backend', 'docs', 'partner-api-catalog.json')
const publicUrl = 'https://api.protegey.com/public/partner-api-catalog'

const argIdx = process.argv.indexOf('--from')
const explicit = (argIdx > -1 ? process.argv[argIdx + 1] : undefined) || process.env.PARTNER_API_CATALOG_SOURCE
const source = explicit || (existsSync(siblingFile) ? siblingFile : publicUrl)

async function load(src) {
    if (/^https?:\/\//.test(src)) {
        const res = await fetch(src, { headers: { accept: 'application/json' } })
        if (!res.ok) throw new Error(`GET ${src} → HTTP ${res.status}`)
        return res.json()
    }
    return JSON.parse(await readFile(resolve(src), 'utf8'))
}

// `validators` lists the backend's internal class-validator decorator names — noise for partners.
function strip(value) {
    if (Array.isArray(value)) return value.map(strip)
    if (value && typeof value === 'object') {
        const out = {}
        for (const [k, v] of Object.entries(value)) if (k !== 'validators') out[k] = strip(v)
        return out
    }
    return value
}

const catalog = strip(await load(source))
if (typeof catalog.catalogVersion !== 'number' || !catalog.modules || !catalog.webhooks?.events) {
    throw new Error(`${source} does not look like a partner-API catalog (missing catalogVersion / modules / webhooks.events)`)
}

const index = {
    catalogVersion: catalog.catalogVersion,
    title: catalog.title,
    generatedFrom: catalog.generatedFrom,
    syncedFrom: /^https?:/.test(source) ? source : 'protegey-backend/docs/partner-api-catalog.json',
    conventions: catalog.conventions,
    sandboxScenarios: catalog.sandboxScenarios,
    webhooks: {
        title: catalog.webhooks.title,
        delivery: catalog.webhooks.delivery,
        events: Object.entries(catalog.webhooks.events).map(([type, ev]) => ({ type, description: ev.description })),
    },
    modules: Object.entries(catalog.modules).map(([key, m]) => ({
        key,
        title: m.title,
        lifecycle: m.lifecycle ?? null,
        endpoints: m.endpoints.map((e) => ({
            id: e.id, method: e.method, path: e.path, summary: e.summary, webhooksFired: e.webhooksFired ?? [],
        })),
        scenarioCount: (m.scenarios ?? []).length,
        responseShapes: Object.keys(m.responses ?? {}),
    })),
}

await rm(outDir, { recursive: true, force: true })
await mkdir(join(outDir, 'modules'), { recursive: true })
await writeFile(join(outDir, 'index.json'), JSON.stringify(index))
for (const [key, m] of Object.entries(catalog.modules)) {
    await writeFile(join(outDir, 'modules', `${key}.json`), JSON.stringify({
        endpoints: m.endpoints, scenarios: m.scenarios ?? [], responses: m.responses ?? {},
    }))
}
await writeFile(join(outDir, 'webhook-events.json'), JSON.stringify(catalog.webhooks.events))

console.log(`partner-API catalog v${catalog.catalogVersion} synced from ${source}`)
console.log(`  ${Object.keys(catalog.modules).length} modules, ${Object.keys(catalog.webhooks.events).length} webhook events → ${outDir}`)
